mapper.select:
/* USE : PosRcvSaleMomsMapper.getPosRcvSaleMomsList */
SELECT TO_CHAR(TO_DATE(SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE , YOIL , BRANCH_NM , STORE_CD , STORE_NM , POS_NO , BILL_NO , SIDE_P_DTL_NO , BILL_DTL_NO , SALE_YN , CHANNEL_ORDER_NO , CHANNEL_ORDER_NO2 , CHANNEL_TYPE , DLVR_ORDER_FG2 , CHANNEL_SERVICE_TYPE , TBL_NM , BILL_DT , L_CLASS_CD , L_CLASS_NM , M_CLASS_CD , M_CLASS_NM , S_CLASS_CD , S_CLASS_NM , PROD_CD , PROD_NM , SEL_TYPE_FG , SIDE_PROD_CD , SALE_QTY1 , SALE_QTY2 , SALE_QTY3 , TOT_SALE_AMT1 , TOT_SALE_AMT2 , TOT_SALE_AMT3 , DC_AMT1 , DC_AMT2 , DC_AMT3 , REAL_SALE_AMT1 , REAL_SALE_AMT2 , REAL_SALE_AMT3 , GA_AMT1 , GA_AMT2 , GA_AMT3 , VAT_AMT1 , VAT_AMT2 , VAT_AMT3 , ORG_SALE_DATE , ORG_POS_NO , ORG_BILL_NO ${sQuery1} FROM ( SELECT tsdpsd.SALE_DATE , TO_CHAR(TO_DATE(tsdpsd.SALE_DATE, 'YYYYMMDD'), 'DY') AS YOIL , (SELECT BRANCH_NM FROM TB_HQ_BRANCH_MOMS thbm WHERE thbm.HQ_OFFICE_CD = tsdpsd.HQ_OFFICE_CD AND thbm.BRANCH_CD = tsdpsd.BRANCH_CD) AS BRANCH_NM , tsdpsd.STORE_CD , tsdpsd.STORE_NM , tsdpsd.POS_NO , tsdpsd.BILL_NO , tsdpsd.SIDE_P_DTL_NO , tsdpsd.BILL_DTL_NO , tsdpsd.SALE_YN , tsdpsd.CHANNEL_ORDER_NO , tsdpsd.CHANNEL_ORDER_NO2 , tsdpsd.CHANNEL_TYPE , tsdpsd.DLVR_ORDER_FG2 , tsdpsd.CHANNEL_SERVICE_TYPE , tsdpsd.TBL_NM , tsdpsd.BILL_DT , tmpcv.L_CLASS_CD , tmpcv.L_CLASS_NM , tmpcv.M_CLASS_CD , tmpcv.M_CLASS_NM , tmpcv.S_CLASS_CD , tmpcv.S_CLASS_NM , tsdpsd.PROD_CD , tsdpsd.ORG_SALE_DATE , tsdpsd.ORG_POS_NO , tsdpsd.ORG_BILL_NO , (CASE tsdpsd.SEL_TYPE_FG WHEN 'P' THEN '사이드모상품' WHEN 'S' THEN '사이드상품' WHEN 'N' THEN '일반판매상품' END) AS SEL_TYPE_FG , (CASE tsdpsd.SEL_TYPE_FG WHEN 'S' THEN tsdpsd.SIDE_PROD_CD END) AS SIDE_PROD_CD , (CASE tsdpsd.SEL_TYPE_FG WHEN 'S' THEN 'ㅤ- ▶ ' || tmps2.PROD_NM ELSE tmps2.PROD_NM END) AS PROD_NM , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.SALE_QTY END) AS SALE_QTY1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.SALE_QTY END) AS SALE_QTY2 , (tsdpsd.SALE_QTY) AS SALE_QTY3 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.SALE_AMT END) AS TOT_SALE_AMT1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.SALE_AMT END) AS TOT_SALE_AMT2 , (tsdpsd.SALE_AMT) AS TOT_SALE_AMT3 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.DC_AMT END) AS DC_AMT1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.DC_AMT END) AS DC_AMT2 , (tsdpsd.DC_AMT) AS DC_AMT3 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.REAL_SALE_AMT END) AS REAL_SALE_AMT1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.REAL_SALE_AMT END) AS REAL_SALE_AMT2 , (tsdpsd.REAL_SALE_AMT) AS REAL_SALE_AMT3 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.GA_AMT END) AS GA_AMT1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.GA_AMT END) AS GA_AMT2 , (tsdpsd.GA_AMT) AS GA_AMT3 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'P' THEN tsdpsd.VAT_AMT END) AS VAT_AMT1 , (CASE WHEN tsdpsd.SEL_TYPE_FG = 'N' OR tsdpsd.SEL_TYPE_FG = 'S' THEN tsdpsd.VAT_AMT END) AS VAT_AMT2 , (tsdpsd.VAT_AMT) AS VAT_AMT3 ${sQuery2} FROM ( SELECT tssh.HQ_OFFICE_CD , tms.BRANCH_CD , tssh.STORE_CD , tms.STORE_NM , tssh.SALE_DATE , tssh.POS_NO , tssh.BILL_NO , tssd.SIDE_P_DTL_NO , tssd.BILL_DTL_NO , tssh.SALE_YN , NVL(tsshd.CHANNEL_ORDER_NO, tssh.STORE_CD || tssh.SALE_DATE || tssh.ORDER_NO) AS CHANNEL_ORDER_NO , tssh.PAGER_NO AS CHANNEL_ORDER_NO2 , tssh.DLVR_IN_FG AS CHANNEL_TYPE , tssh.DLVR_ORDER_FG AS DLVR_ORDER_FG2 , CASE WHEN tssh.TBL_CD = '000' THEN 'POS' WHEN tssh.TBL_CD = '998' THEN 'KIOSK' WHEN tssh.TBL_CD = '997' THEN 'DT' WHEN tssh.DLVR_IN_FG = '1' THEN 'CID' WHEN tsshd.DLVR_IN_SVC_NM IS NOT NULL THEN tsshd.DLVR_IN_SVC_NM ELSE NULL END AS CHANNEL_SERVICE_TYPE , tmt.TBL_NM AS TBL_NM , TO_CHAR(TO_DATE(tssh.BILL_DT,'yyyy/mm/dd hh24:mi:ss'),'hh24:mi:ss') AS BILL_DT , tssd.SALE_QTY , tssd.SALE_AMT , tssd.DC_AMT , tssd.REAL_SALE_AMT , (tssd.REAL_SALE_AMT - tssd.VAT_AMT) AS GA_AMT , tssd.VAT_AMT , CASE WHEN ( tssd.SIDE_P_DTL_NO = tssd.BILL_DTL_NO OR tssd.SIDE_P_PROD_CD = tssd.PROD_CD OR ( tssd.SIDE_P_DTL_NO IS NOT NULL AND TRIM(tssd.SIDE_P_PROD_CD) IS NULL ) ) THEN ( CASE WHEN tssd.SINGLE_PROD_CD IS NOT NULL THEN 'N' ELSE 'P' END ) WHEN ( tssd.SIDE_P_DTL_NO != tssd.BILL_DTL_NO AND TRIM(tssd.SIDE_P_PROD_CD) IS NOT NULL ) THEN 'S' ELSE 'N' END AS SEL_TYPE_FG , tssd.DLVR_IN_FG , tssd.DLVR_ORDER_FG , CASE WHEN SIDE_P_DTL_NO != BILL_DTL_NO AND TRIM(SIDE_P_PROD_CD) IS NOT NULL THEN SIDE_P_PROD_CD ELSE PROD_CD END AS PROD_CD , CASE WHEN SIDE_P_DTL_NO != BILL_DTL_NO AND TRIM(SIDE_P_PROD_CD) IS NOT NULL THEN PROD_CD ELSE PROD_CD END AS SIDE_PROD_CD , TO_CHAR(TO_DATE(SUBSTR(tssh.ORG_BILL_NO,-14,8), 'yyyymmdd'), 'yyyy-mm-dd') AS ORG_SALE_DATE , SUBSTR(tssh.ORG_BILL_NO,-6,2) AS ORG_POS_NO , SUBSTR(tssh.ORG_BILL_NO,-4) AS ORG_BILL_NO FROM TB_SL_SALE_HDR tssh , TB_SL_SALE_HDR_DLVR tsshd , TB_SL_SALE_DTL tssd , TB_MS_TABLE_V01 tmt , TB_MS_STORE tms , TB_MS_STORE_INFO tmsi WHERE tssd.HQ_OFFICE_CD = tssh.HQ_OFFICE_CD AND tssd.STORE_CD = tssh.STORE_CD AND tssd.SALE_DATE = tssh.SALE_DATE AND tssd.POS_NO = tssh.POS_NO AND tssd.BILL_NO = tssh.BILL_NO AND tsshd.HQ_OFFICE_CD (+) = tssh.HQ_OFFICE_CD AND tsshd.STORE_CD (+) = tssh.STORE_CD AND tsshd.SALE_DATE (+) = tssh.SALE_DATE AND tsshd.POS_NO (+) = tssh.POS_NO AND tsshd.BILL_NO (+) = tssh.BILL_NO AND tmt.STORE_CD (+) = tssd.STORE_CD AND tmt.TBL_CD (+) = tssh.TBL_CD AND tms.HQ_OFFICE_CD = #{hqOfficeCd} AND tssh.HQ_OFFICE_CD = tms.HQ_OFFICE_CD AND tssh.STORE_CD = tms.STORE_CD AND tmsi.STORE_CD (+) = tms.STORE_CD AND tssh.SALE_DATE = #{saleDate} AND tssh.STORE_CD = #{storeCd}
) tsdpsd , TB_MS_PRODUCT tmp , TB_MS_PRODUCT tmps2 -- 사이드 , TB_HQ_PRODUCT_CLASS_V03 tmpcv WHERE 1=1 AND tmp.STORE_CD = tsdpsd.STORE_CD AND tmp.PROD_CD = tsdpsd.PROD_CD AND tmps2.STORE_CD = tsdpsd.STORE_CD AND tmps2.PROD_CD = tsdpsd.SIDE_PROD_CD AND tsdpsd.HQ_OFFICE_CD = tmpcv.HQ_OFFICE_CD AND tmps2.PROD_CLASS_CD = tmpcv.PROD_CLASS_CD ) A ORDER BY A.STORE_CD ASC, A.SALE_DATE, A.POS_NO, A.BILL_NO, A.SIDE_P_DTL_NO, A.BILL_DTL_NO
